// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        (bool sent1, ) = address(c).call{value: 1 ether}("");
        require(sent1);
        vm.prank(address(this));
        c.sendMoney(address(0xdead), 0.5 ether);
        address nonOwner = address(0xbabe);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call{value: 0.5 ether}("");
        require(ok);
        bool success;
        address target = address(c);
        uint amount = 0.5 ether;
        vm.prank(nonOwner);
        try c.sendMoney(target, amount) {
            success = true;
        } catch {
            success = false;
        }
        uint balanceAfter = address(c).balance;
        assertTrue(success == false && balanceAfter == 1 ether);
    }
}
